//! 📖️ Individually authored persisted Playbook document and typed child addresses.
use super::PlaybookSnapshot;
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabase,SqliteSnapshotControl,SqliteSnapshotPhase,SnapshotEncoding,validate_sqlite_database_schema,artifact::{Cell,Projection,Reconstruction,NativeEncodingBound}}};
#[path="📏️native/🦀️.rs"]mod native;
impl ArtifactSqliteSnapshot for PlaybookSnapshot{
 const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
 fn to_sqlite_database(&self,c:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{let mut p=Projection::new(Self::SQLITE_SCHEMA,c)?;p.check_rows(3)?;p.insert("playbook_document",&[Cell::Text(&self.schema),Cell::Text(&self.id),Cell::Text(&self.version),self.title.as_deref().map(Cell::Text).unwrap_or(Cell::Null)])?;let n=&self.document;let nt=&n.target;let nd=&nt.dialect;p.insert("playbook_narrative_child",&[Cell::Text(&n.child_id),Cell::Text(&nt.artifact_id),Cell::Text(&nd.artifact_kind),Cell::Text(&nd.standard),Cell::Text(&nd.subset)])?;let f=&self.flow;let ft=&f.target;let fd=&ft.dialect;p.insert("playbook_flow_child",&[Cell::Text(&f.child_id),Cell::Text(&ft.artifact_id),Cell::Text(&fd.artifact_kind),Cell::Text(&fd.standard),Cell::Text(&fd.subset)])?;p.finish()}
 fn from_sqlite_database(d:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{validate_sqlite_database_schema(d,Self::SQLITE_SCHEMA,c.limits()).map_err(|e|e.to_string())?;c.check_database(d,SqliteSnapshotPhase::ReconstructSnapshot)?;let p=d.table("playbook_document")?.single_row()?;let n=d.table("playbook_narrative_child")?.single_row()?;let f=d.table("playbook_flow_child")?.single_row()?;if p.rowid!=1||n.rowid!=1||f.rowid!=1||p.integer(0)?!=1||n.integer(0)?!=1||f.integer(0)?!=1||p.values.len()!=5||n.values.len()!=6||f.values.len()!=6{return Err("Playbook requires exact identity-1 parent and child rows".into())}let mut r=Reconstruction::new(c)?;let schema=r.text(p.text(1)?)?;let id=r.text(p.text(2)?)?;let version=r.text(p.text(3)?)?;let title=p.optional_text(4)?.map(|s|r.text(s)).transpose()?;let document=store::ArtifactChild::new(r.text(n.text(1)?)?,store::os_io::ArtifactRef{artifact_id:r.text(n.text(2)?)?,dialect:store::os_io::ArtifactDialect{artifact_kind:r.text(n.text(3)?)?,standard:r.text(n.text(4)?)?,subset:r.text(n.text(5)?)?}});let flow=store::ArtifactChild::new(r.text(f.text(1)?)?,store::os_io::ArtifactRef{artifact_id:r.text(f.text(2)?)?,dialect:store::os_io::ArtifactDialect{artifact_kind:r.text(f.text(3)?)?,standard:r.text(f.text(4)?)?,subset:r.text(f.text(5)?)?}});r.checkpoint()?;Ok(Self{schema,id,version,title,document,flow})}
 fn preflight_sqlite_snapshot_encoding(&self,_encoding:SnapshotEncoding,c:&mut SqliteSnapshotControl<'_>)->Result<(),String>{let mut b=NativeEncodingBound::new(c)?;b.add(8192)?;for text in[&self.schema,&self.id,&self.version]{b.repeated(text.len(),16)?}if let Some(title)=&self.title{b.repeated(title.len(),16)?}let n=&self.document;let nt=&n.target;let nd=&nt.dialect;let f=&self.flow;let ft=&f.target;let fd=&ft.dialect;for text in[&n.child_id,&nt.artifact_id,&nd.artifact_kind,&nd.standard,&nd.subset,&f.child_id,&ft.artifact_id,&fd.artifact_kind,&fd.standard,&fd.subset]{b.repeated(text.len(),16)?}native::local_scene(&self.flow,&mut b)?;b.finish()}
 fn validate_sqlite_snapshot_subset(&self,dialect:&store::os_io::ArtifactDialect,d:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->store::io_schema::IoResult<()>{c.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,1)?;if dialect.artifact_kind!="s.playbook.playbook"||dialect.standard!="1"||dialect.subset!="*"{return Err(String::from("Playbook dialect differs from its owned wildcard").into())}if d.table("playbook_document")?.single_row()?.text(1)?!=self.schema{return Err(String::from("Playbook projected schema differs").into())}c.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,1,1)?;Ok(store::io_schema::IoOutcome::clean(()))}
}
